41	
42	        static SheetView of(Sheet sheet) {
43	            return new SheetView(sheet.getId(), sheet.getToday(), sheet.getFloor().toPlainString(), sheet.getTerms(),
44	                    sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
45	                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
46	                    DatedValue.of(sheet.floorHistory()), DatedValue.of(sheet.latePctHistory()), sheet.isArchived(),
47	                    graceHistory(sheet), sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch(),
48	                    sheet.getPot() == null ? null : sheet.getPot().toPlainString(), sheet.getParentId());
49	        }
50	
51	        /** Each grade's grace values by from-date, its starting value (none) first. */
52	        static Map<String, List<DatedValue>> graceHistory(Sheet sheet) {
53	            Map<String, List<DatedValue>> all = new TreeMap<>();
54	            for (String grade : GRADES) {
55	                all.put(grade, DatedValue.of(sheet.gradeGraceHistory(grade)));
56	            }
57	            return all;
58	        }
59	    }
