102	            Map<String, String> all = new TreeMap<>();
103	            for (String grade : GRADES) {
104	                BigDecimal threshold = sheet.getGradeProofThreshold(grade);
105	                all.put(grade, threshold == null ? null : threshold.toPlainString());
106	            }
107	            return all;
