111	        private static Map<String, String> permissions(Sheet sheet) {
112	            Map<String, String> all = new TreeMap<>();
113	            Sheet.STANDING_PERMISSIONS.keySet().forEach(action -> {
114	                String roles = sheet.getPermission(action);
115	                all.put(action, roles == null ? "" : roles);
116	            });
117	            return all;
118	        }
