212	    /** A date as entered; null when blank. */
213	    static LocalDate parse(String value) {
214	        String text = value == null ? "" : value.trim();
215	        try {
216	            return text.isEmpty() ? null : LocalDate.parse(text);
217	        } catch (DateTimeParseException e) {
218	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + text);
219	        }
220	    }
