    }

    private static PersonState kept(Person p) {
        return new PersonState(p.getId(), p.getName(), p.getGrade(),
                p.getGradesFrom().entrySet().stream().map(e -> new GradeState(e.getKey(), e.getValue())).toList(),
                p.getTerms(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList(),
                p.getRetiredFrom(), p.getContact(), p.getAliases(),
                p.getRetirements().stream().map(r -> new RetirementState(r.getFromDate(), r.getToDate())).toList());
    }

    private static ClaimState kept(Claim c) {
        return new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(), c.getDueBy(), c.getStatus(),
                c.getNumber(), c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getCorrects(), c.getDeferredUntil());
    }
}
package net.officefloor.hq.app.history;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Lob;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** The sheet as it stood at the end of a date, kept as JSON (see {@link SheetHistory}). */
@Entity
@Table(name = "sheet_snapshot")
public class SheetSnapshot {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    /** The sheet's today the snapshot was kept on leaving. */
    @Column(name = "as_of", nullable = false)
    private LocalDate asOf;

    @Lob
    @Column(name = "state", nullable = false)
    private String state;

    /** What the screen is told about the sheet as it stood then (see {@link SheetHistory.Views}); null on older snapshots. */
    @Lob
    @Column(name = "views")
    private String views;

    protected SheetSnapshot() {
    }

    public SheetSnapshot(String sheetId, LocalDate asOf, String state, String views) {
        this.sheetId = sheetId;
        this.asOf = asOf;
        this.state = state;
        this.views = views;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public LocalDate getAsOf() {
        return asOf;
    }

    public String getState() {
        return state;
    }

    public String getViews() {
        return views;
    }
}

