== V45__claim_locked_by.sql
-- The user whose open editor locks the claim for everyone else; null when no editor holds it. Taken
-- by the edit button, released when the editor is saved or cancelled or the sheet's today changes.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(200);
== V46__period_soft_closed.sql
-- A period may be soft-closed: its due-total and each person's figure for it are fixed (closed_total
-- and period_person_total, as on a close), while claims dated in it can still change. A claim added
-- while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN NOT NULL DEFAULT FALSE;
== V47__person_statement.sql
-- Each statement taken for a person, numbered from 1 in the order taken, with its due-total (null
-- when n/a) and date (the sheet's today). Cancelling the last statement removes its row, and the
-- person shows the one before it again. A person's last statement taken before this table is kept
-- here; any earlier ones were not recorded, so cancelling back past it shows no statement.
CREATE TABLE person_statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    seq       INT            NOT NULL,
    total     DECIMAL(14, 2),
    taken_on  DATE           NOT NULL,
    UNIQUE (person_id, seq)
);
INSERT INTO person_statement (sheet_id, person_id, seq, total, taken_on)
    SELECT sheet_id, id, statement_count, statement_total, statement_date
    FROM person WHERE statement_count > 0 AND statement_date IS NOT NULL;
== V48__sheet_snapshot.sql
-- The sheet as it stood at the end of a date: kept as the sheet's today moves on from that date, with
-- everything its figures are read from (settings, rates, people and claims) as JSON. A statement taken
-- as of a past date reads the last one kept for a date on or before it.
CREATE TABLE sheet_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    as_of     DATE           NOT NULL,
    state     CLOB           NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, as_of);
== V49__sheet_snapshot_views.sql
-- What the screen is told about the sheet as it stood at the end of the snapshot's date (its people,
-- claims, rates and periods, and whether it was archived) as JSON, so a user's screen can show the
-- sheet as of a past date. Null on snapshots kept before this column.
ALTER TABLE sheet_snapshot ADD COLUMN views CLOB;
== V50__sheet_entry_date.sql
-- Entry date: while set, the default date of a new claim wherever the sheet's today was (the claim
-- form, the quick-add bar, a pasted line with a blank date and a correction); null: off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
== V51__claim_reminded_on.sql
-- The last day (the sheet's today) a reminder was written for the claim; null when never reminded.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
== V52__holiday.sql
-- A holiday on a sheet: a date, on the sheet's list at most once. A claim's due-by, fixed when it
-- is added, is moved past the holidays on the list then.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(64) NOT NULL REFERENCES sheet (id),
    holiday_date DATE        NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);
== V54__claim_ref.sql
-- A claim's external reference (null: none), and its key (lower case): a reference is used at most once on a sheet.
ALTER TABLE claim ADD COLUMN ref VARCHAR(200);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(200);
CREATE UNIQUE INDEX claim_sheet_ref ON claim (sheet_id, ref_key);
== V55__claim_tags.sql
-- A claim's tags: trimmed, lower case, no repeats, sorted and comma separated (null: none); and every
-- tag it has ever carried, in the same form (null: none), so the sheet lists each tag ever used on it.
ALTER TABLE claim ADD COLUMN tags VARCHAR(2000);
ALTER TABLE claim ADD COLUMN tags_used VARCHAR(4000);
== V56__void_reason.sql
-- A void reason on a sheet: trimmed text, on the sheet's list at most once. While the list is not
-- empty a claim is voided only with a reason from it, which the claim keeps (null: voided without one).
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(100);
== V57__claim_comment.sql
-- A claim's comments, oldest first (by id): the text as written (trimmed, never blank), with the user
-- who wrote it and the sheet's today when it was written.
CREATE TABLE claim_comment (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id   BIGINT         NOT NULL REFERENCES claim (id),
    by_user    VARCHAR(200)   NOT NULL,
    on_date    DATE           NOT NULL,
    text       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_comment_claim ON claim_comment (claim_id, id);
== V58__claim_edited_by.sql
-- The user who last edited the claim (through its form or its row's amount entry); null when never
-- edited. Like its opener, that user cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(200);
== V59__settle_batch.sql
-- Settle batches: a bulk settle that settles (or sends PENDING) at least one claim is a batch,
-- numbered 1, 2, ... on the sheet in the order the batches happen. Each claim it settled keeps its
-- batch number (null for a claim settled one at a time); the sheet keeps the last it gave out.
ALTER TABLE sheet ADD COLUMN last_settle_batch INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN settle_batch INT;
== V60__person_contact.sql
-- A person's contact: kept with surrounding spaces removed and lower-cased; null when they have
-- none. A contact is held by at most one person on the sheet.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
== V61__person_alias.sql
-- A person's aliases: other names they go by, each kept with surrounding spaces removed and with
-- its key (ignoring case). An alias shares the names' uniqueness on the sheet: no alias equals,
-- by key, any name or other alias there.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL,
    PRIMARY KEY (person_id, alias_key)
);
== V62__claim_template.sql
-- A claim template on a sheet: a name (trimmed, once per sheet), an amount and a note. Saving a name
-- again replaces its amount and note. A claim made from one copies them, so later changes leave it be.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL,
    note     VARCHAR(500)   NOT NULL
);
CREATE UNIQUE INDEX claim_template_sheet_name ON claim_template (sheet_id, name);
== V63__pool.sql
-- A pool on a sheet: a name (trimmed, once per sheet) and its members.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

-- A pool's member: a person on the sheet, in the pool at most once, with a share percent (more than
-- 0.00, at most 100.00). A person may be in several pools.
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
== V64__sheet_pot.sql
-- The sheet's pot: split among each balanced pool's members as their cuts. Null means none.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(14, 2);
== V65__claim_listed.sql
-- The place a claim is listed at: claims are listed newest first by it. A claim takes the next value
-- when it is added, and again when it moves to another person by a merge, so the moved claims are
-- listed after (newer than) that person's own, in the order they were added.
CREATE SEQUENCE claim_listed_seq START WITH 1;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
== V66__person_patron_order.sql
-- A person's patrons are kept in the order they were named: their shares are split in that order.
-- Patrons named before this are taken in the order of their ids.
ALTER TABLE person_patron ADD COLUMN patron_order INT;
UPDATE person_patron pp SET patron_order = (
    SELECT COUNT(*) FROM person_patron q WHERE q.person_id = pp.person_id AND q.patron_id < pp.patron_id);
ALTER TABLE person_patron ALTER COLUMN patron_order SET NOT NULL;
ALTER TABLE person_patron DROP PRIMARY KEY;
ALTER TABLE person_patron ADD PRIMARY KEY (person_id, patron_order);
== V67__sheet_parent.sql
-- The sheet's parent: a sheet whose rates apply where this sheet has none in force. Null means none.
ALTER TABLE sheet ADD COLUMN parent_id VARCHAR(64);
== V68__claim_deleted.sql
-- A DRAFT claim may now be DELETED: it counts nowhere, and may be restored to a DRAFT on the sheet's
-- today it was deleted.
ALTER TABLE claim ADD COLUMN next_status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL
    CHECK (next_status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED'));
UPDATE claim SET next_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN next_status RENAME TO status;
== V69__pool_member_pool.sql
-- A pool's member may be another pool instead of a person, with a share like a person's. A pool is a
-- member of at most one pool; exactly one of person_id and member_pool_id is set.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_one_kind
    CHECK ((person_id IS NULL) <> (member_pool_id IS NULL));
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);
==

file.content:
== V1__sheet.sql
-- A sheet: the unit everything else in the app is kept per. Created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(64) PRIMARY KEY,
    created_at TIMESTAMP   NOT NULL
);
== V2__sheet_today.sql
-- The sheet's "today": the date every date-dependent decision and default date on the sheet uses,
-- never the real clock. A new sheet starts on the real date; it is changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- A person on a sheet: a name and a grade (A, B or C). Listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on the sheet, ignoring case and surrounding spaces. Names are kept
-- with surrounding spaces removed; name_key is the name lower-cased, the key the uniqueness is on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A claim a person on a sheet makes: an amount (0.00 or more, two decimals), a date and a note
-- (may be empty). Listed under its person newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(500)   NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
== V6__rate.sql
-- The rate for a grade on a sheet: a percent with two decimals (0.00 or more). A sheet holds at
-- most one rate per grade; a grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)   NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)       NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID.
-- Only OPEN and SETTLED claims count toward what is claimed and due.
ALTER TABLE claim ADD COLUMN status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- A claim's number: when a claim is opened it takes the sheet's next number (1, 2, ...), with no
-- gaps and never reused. A DRAFT claim has none, and voiding a claim clears it. The sheet keeps the
-- last number it gave out; opening a claim takes the sheet row's lock to bump it.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
ALTER TABLE claim ADD CONSTRAINT claim_number_unique UNIQUE (sheet_id, claim_number);
== V9__claim_settled_due.sql
-- A claim's due fixed when it is settled: its amount at the person's grade's rate at that moment,
-- rounded half up to two decimals; later changes to rates do not alter it. Null while the claim is
-- not settled, and when the grade had no rate at settling (its due then stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
== V10__rate_from.sql
-- A rate may carry a from-date: it applies to claims dated on or after it, until the next rate's
-- from-date for the same grade. A rate with no from-date applies from the beginning of time. A
-- sheet holds at most one rate per grade and from-date (one with none per grade, kept by the app).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
== V11__claim_opened_by.sql
-- Who opened a claim: the signed-in user's name, set when the claim is opened. Null while DRAFT, and
-- for a claim voided before it was opened. That user cannot settle the claim (four eyes).
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(200);
== V12__person_version.sql
-- The version of a person: raised on every save, so an editor that loaded an older version is refused.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== V13__statement.sql
-- A person's statements: how many have been taken, and the due-total and date (the sheet's today) of
-- the last one. The last due-total is null with no statement, or when it was n/a.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN statement_total DECIMAL(14, 2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: stated, with the due figure it had then (null when
-- it was n/a). A claim that did not count at the statement is left unbound, its due live again.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
== V14__period.sql
-- A period on a sheet: a name, unique on the sheet ignoring case and surrounding spaces (name_key is
-- the trimmed name lower-cased), and a from and to date, both inclusive. No two periods on a sheet
-- overlap (kept by the app). A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
== V15__period_closed.sql
-- A period can be closed: closing fixes its due-total at that moment (closed_total), so later
-- changes to rates do not alter it. Null while the period is open. No claim dated inside a closed
-- period can be added, edited or moved through its statuses.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
== V16__person_retired.sql
-- A person can be retired from a date: no claim dated after it can be added for them. Null while
-- they are not retired. A retired person's claims keep counting in every total.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no
-- live total (their own, the sheet's, a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
== V18__role_clerk_limit.sql
-- The role a user name has on a sheet: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- The sheet's clerk limit: a clerk can settle a claim only when its due is at or below it (a claim
-- whose due is n/a is within any limit). Null means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2);
== V19__sheet_floor.sql
-- The sheet's floor: a claim's live due is at least it. Settled, stated and closed figures keep
-- what they were fixed at.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL;
== V20__sheet_terms.sql
-- The sheet's terms: the number of days after its date a claim is due by. An OPEN claim whose
-- due-by is before the sheet's today is overdue.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
== V21__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every
-- full 30 days it is overdue. Never bound by a statement; frozen in when the claim is settled.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL;
== V22__person_patron.sql
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id),
    CHECK (person_id <> patron_id)
);
== V23__person_grade_from.sql
-- A person's grade is dated: the grade on the person row is the first they were given, applying from
-- the beginning of time; each later grade is recorded here from its date, one per date, and holds
-- from that date until the next.
CREATE TABLE person_grade (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    from_date DATE    NOT NULL,
    grade     CHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    PRIMARY KEY (person_id, from_date)
);
== V24__claim_corrects.sql
-- A correction: a claim with a negative amount, naming by number a SETTLED claim of the same person
-- that it corrects. Null on any other claim. The amount may now be below 0.00, but only on a
-- correction.
ALTER TABLE claim ADD COLUMN corrects INT;
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(14, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
== V25__sheet_policy_date.sql
-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or
-- after it half to even (a correction by the date of the claim it corrects). Null means the sheet's
-- today. Settled and stated figures keep what they were fixed at.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
== V26__period_numbering.sql
-- Period numbering: from the sheet's period-numbering-from date (null: off), a claim opened while the
-- sheet's today is on or after it is numbered within the period its date falls in, <period name>-<n>,
-- counting from 1 in each period (the period keeps the last it gave out), or X-<n> in the sheet's own
-- sequence for a claim in no period. Claims numbered before keep their sheet-wide numbers, and the
-- sheet-wide sequence carries on when the setting is cleared. A claim's number, and the number a
-- correction names, are now text.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE sheet ADD COLUMN last_unperiod_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE period ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(220);
== V27__claim_pending.sql
-- A claim may now be PENDING: settled by a clerk above the clerk limit, awaiting a steward's approval.
-- It counts toward what is claimed and due, like an OPEN one.
ALTER TABLE claim ADD COLUMN next_status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL
    CHECK (next_status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
UPDATE claim SET next_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN next_status RENAME TO status;
== V28__grade_terms.sql
-- Terms per grade: a grade's own terms in days; null means the grade uses the sheet's terms.
ALTER TABLE sheet ADD COLUMN terms_a INT;
ALTER TABLE sheet ADD COLUMN terms_b INT;
ALTER TABLE sheet ADD COLUMN terms_c INT;
-- A claim's due-by is fixed when it is added, from the terms of its person's grade in force on its
-- date; later changes to the terms or the claim's date do not move it. Existing claims take their
-- date plus the sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V29__claim_log.sql
-- A claim's status log: one line per status it has had, oldest first (by id), with the user who
-- moved it there, the sheet's today then, and the claim's due as computed at that moment (null: n/a).
-- Claims added before the log have no lines.
CREATE TABLE claim_log (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id   BIGINT         NOT NULL REFERENCES claim (id),
    status     VARCHAR(16)    NOT NULL,
    by_user    VARCHAR(200)   NOT NULL,
    on_date    DATE           NOT NULL,
    due        DECIMAL(14, 2)
);
CREATE INDEX claim_log_claim ON claim_log (claim_id, id);
== V30__person_hold.sql
-- A hold has a from-date and an optional to-date (null: open-ended), and a person may have several
-- over time. Only their OPEN and PENDING claims dated within a hold, and not bound by a statement,
-- are left out of the live totals. A person on hold before this kept it for all dates: their hold
-- now runs from the earliest date there is.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE,
    CHECK (to_date IS NULL OR to_date >= from_date)
);
INSERT INTO person_hold (person_id, from_date, to_date)
    SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V31__rate_to.sql
-- A rate may carry a to-date: it applies through it, and a claim dated after it has no rate unless a
-- later rate of the grade is in force on its date. A rate with no to-date applies until the next
-- rate's from-date. A to-date is never before the rate's from-date.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_after_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
== V32__sheet_cap.sql
-- The sheet's cap: a person's due-total is at most it, the excess shown apart. Null means no cap.
ALTER TABLE sheet ADD COLUMN cap DECIMAL(14, 2);
== V33__period_person_total.sql
-- Closing a period also fixes each person's due-total for it at that moment, one row per person then
-- on the sheet; a person added later has no row and shows 0.00 for it. Reopening removes the rows.
-- The period's closed_total is the sum of these.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V34__sheet_setting_from.sql
-- Dated settings: a setting that carries a figure (the floor, the late percent, the terms, each
-- grade's terms, the clerk limit and the cap) holds a value per from-date. The value in force on a
-- date is the one with the latest from-date on or before it; before every from-date it is the
-- sheet's own column (its starting value). A sheet holds at most one value per key and from-date.
-- A null value means none (no limit, no cap, or the sheet's terms for a grade).
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(64) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(32) NOT NULL,
    from_date     DATE        NOT NULL,
    setting_value VARCHAR(32)
);
CREATE UNIQUE INDEX sheet_setting_key_from ON sheet_setting (sheet_id, setting_key, from_date);
== V35__claim_deferred.sql
-- An OPEN claim may be deferred to a date after the sheet's today: until the sheet's today reaches
-- it, the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
-- statement. Null when never deferred; the date is kept once reached.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V36__claim_proofs.sql
-- A claim's proofs count, raised by one at a time while the claim is neither SETTLED nor VOID.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- The sheet's starting proof threshold (before every from-date, see sheet_setting): a claim whose
-- due is above the threshold in force on its date cannot be settled or approved with no proofs.
-- Null means none.
ALTER TABLE sheet ADD COLUMN proof_threshold DECIMAL(14, 2);
== V37__sheet_permission.sql
-- The permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles that
-- may take it, as a comma separated list. An action with no row keeps its standing rule.
CREATE TABLE sheet_permission (
    sheet_id    VARCHAR(64) NOT NULL REFERENCES sheet (id),
    action      VARCHAR(16) NOT NULL,
    roles       VARCHAR(64) NOT NULL
);
CREATE UNIQUE INDEX sheet_permission_action ON sheet_permission (sheet_id, action);
== V38__role_viewer.sql
-- A user name may now be a viewer: it sees the whole sheet but can change nothing on it.
ALTER TABLE sheet_role ADD COLUMN next_role VARCHAR(16) DEFAULT 'clerk' NOT NULL
    CHECK (next_role IN ('clerk', 'steward', 'viewer'));
UPDATE sheet_role SET next_role = role;
ALTER TABLE sheet_role DROP COLUMN role;
ALTER TABLE sheet_role ALTER COLUMN next_role RENAME TO role;
ALTER TABLE sheet_role ALTER COLUMN role DROP DEFAULT;
== V39__sheet_grace_days.sql
-- Grace days: when the sheet's today is changed, every open period whose to-date plus them is before
-- the new today closes itself; null for off.
ALTER TABLE sheet ADD COLUMN grace_days INT;
== V40__claim_split_from.sql
-- An OPEN claim may be split: the new claim, OPEN with the split-off amount, names the number of the
-- claim it was split from. Null on any other claim (the original names nothing).
ALTER TABLE claim ADD COLUMN split_from VARCHAR(220);
== V41__person_watch.sql
-- A user watching a person on a sheet: when one of the person's claims is settled, approved or
-- re-settled, each watcher is notified, in the order they started watching (by id). A user watches
-- a person at most once; stopping removes the row, so watching again starts a new place in order.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
== V42__steward_delegation.sql
-- A steward delegating the steward role to a user name for an inclusive range of the sheet's today:
-- while the sheet's today is inside it, the user acts as a steward, on behalf of the steward.
CREATE TABLE steward_delegation (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    steward   VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX steward_delegation_user ON steward_delegation (sheet_id, user_name);
== V43__sheet_archived.sql
-- Archived: once a steward archives a sheet, everything on it stays visible but nothing on it may change.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
== V44__person_terms.sql
-- A person's own terms in days; null when the person has none and takes their grade's (or the
-- sheet's) terms. A claim's due-by is fixed when it is added from the first of the person's own
-- terms, their grade's terms and the sheet's terms in force on its date.
ALTER TABLE person ADD COLUMN terms INT CHECK (terms >= 0);
== V45__claim_locked_by.sql
-- The user whose open editor locks the claim for everyone else; null when no editor holds it. Taken
-- by the edit button, released when the editor is saved or cancelled or the sheet's today changes.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(200);
== V46__period_soft_closed.sql
-- A period may be soft-closed: its due-total and each person's figure for it are fixed (closed_total
-- and period_person_total, as on a close), while claims dated in it can still change. A claim added
-- while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN NOT NULL DEFAULT FALSE;
== V47__person_statement.sql
-- Each statement taken for a person, numbered from 1 in the order taken, with its due-total (null
-- when n/a) and date (the sheet's today). Cancelling the last statement removes its row, and the
-- person shows the one before it again. A person's last statement taken before this table is kept
-- here; any earlier ones were not recorded, so cancelling back past it shows no statement.
CREATE TABLE person_statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    seq       INT            NOT NULL,
    total     DECIMAL(14, 2),
    taken_on  DATE           NOT NULL,
    UNIQUE (person_id, seq)
);
INSERT INTO person_statement (sheet_id, person_id, seq, total, taken_on)
    SELECT sheet_id, id, statement_count, statement_total, statement_date
    FROM person WHERE statement_count > 0 AND statement_date IS NOT NULL;
== V48__sheet_snapshot.sql
-- The sheet as it stood at the end of a date: kept as the sheet's today moves on from that date, with
-- everything its figures are read from (settings, rates, people and claims) as JSON. A statement taken
-- as of a past date reads the last one kept for a date on or before it.
CREATE TABLE sheet_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    as_of     DATE           NOT NULL,
    state     CLOB           NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, as_of);
== V49__sheet_snapshot_views.sql
-- What the screen is told about the sheet as it stood at the end of the snapshot's date (its people,
-- claims, rates and periods, and whether it was archived) as JSON, so a user's screen can show the
-- sheet as of a past date. Null on snapshots kept before this column.
ALTER TABLE sheet_snapshot ADD COLUMN views CLOB;
== V50__sheet_entry_date.sql
-- Entry date: while set, the default date of a new claim wherever the sheet's today was (the claim
-- form, the quick-add bar, a pasted line with a blank date and a correction); null: off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
== V51__claim_reminded_on.sql
-- The last day (the sheet's today) a reminder was written for the claim; null when never reminded.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
== V52__holiday.sql
-- A holiday on a sheet: a date, on the sheet's list at most once. A claim's due-by, fixed when it
-- is added, is moved past the holidays on the list then.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(64) NOT NULL REFERENCES sheet (id),
    holiday_date DATE        NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);
== V54__claim_ref.sql
-- A claim's external reference (null: none), and its key (lower case): a reference is used at most once on a sheet.
ALTER TABLE claim ADD COLUMN ref VARCHAR(200);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(200);
CREATE UNIQUE INDEX claim_sheet_ref ON claim (sheet_id, ref_key);
== V55__claim_tags.sql
-- A claim's tags: trimmed, lower case, no repeats, sorted and comma separated (null: none); and every
-- tag it has ever carried, in the same form (null: none), so the sheet lists each tag ever used on it.
ALTER TABLE claim ADD COLUMN tags VARCHAR(2000);
ALTER TABLE claim ADD COLUMN tags_used VARCHAR(4000);
== V56__void_reason.sql
-- A void reason on a sheet: trimmed text, on the sheet's list at most once. While the list is not
-- empty a claim is voided only with a reason from it, which the claim keeps (null: voided without one).
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(100);
== V57__claim_comment.sql
-- A claim's comments, oldest first (by id): the text as written (trimmed, never blank), with the user
-- who wrote it and the sheet's today when it was written.
CREATE TABLE claim_comment (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id   BIGINT         NOT NULL REFERENCES claim (id),
    by_user    VARCHAR(200)   NOT NULL,
    on_date    DATE           NOT NULL,
    text       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_comment_claim ON claim_comment (claim_id, id);
== V58__claim_edited_by.sql
-- The user who last edited the claim (through its form or its row's amount entry); null when never
-- edited. Like its opener, that user cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(200);
== V59__settle_batch.sql
-- Settle batches: a bulk settle that settles (or sends PENDING) at least one claim is a batch,
-- numbered 1, 2, ... on the sheet in the order the batches happen. Each claim it settled keeps its
-- batch number (null for a claim settled one at a time); the sheet keeps the last it gave out.
ALTER TABLE sheet ADD COLUMN last_settle_batch INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN settle_batch INT;
== V60__person_contact.sql
-- A person's contact: kept with surrounding spaces removed and lower-cased; null when they have
-- none. A contact is held by at most one person on the sheet.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
== V61__person_alias.sql
-- A person's aliases: other names they go by, each kept with surrounding spaces removed and with
-- its key (ignoring case). An alias shares the names' uniqueness on the sheet: no alias equals,
-- by key, any name or other alias there.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL,
    PRIMARY KEY (person_id, alias_key)
);
== V62__claim_template.sql
-- A claim template on a sheet: a name (trimmed, once per sheet), an amount and a note. Saving a name
-- again replaces its amount and note. A claim made from one copies them, so later changes leave it be.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL,
    note     VARCHAR(500)   NOT NULL
);
CREATE UNIQUE INDEX claim_template_sheet_name ON claim_template (sheet_id, name);
== V63__pool.sql
-- A pool on a sheet: a name (trimmed, once per sheet) and its members.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

-- A pool's member: a person on the sheet, in the pool at most once, with a share percent (more than
-- 0.00, at most 100.00). A person may be in several pools.
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
== V64__sheet_pot.sql
-- The sheet's pot: split among each balanced pool's members as their cuts. Null means none.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(14, 2);
== V65__claim_listed.sql
-- The place a claim is listed at: claims are listed newest first by it. A claim takes the next value
-- when it is added, and again when it moves to another person by a merge, so the moved claims are
-- listed after (newer than) that person's own, in the order they were added.
CREATE SEQUENCE claim_listed_seq START WITH 1;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
== V66__person_patron_order.sql
-- A person's patrons are kept in the order they were named: their shares are split in that order.
-- Patrons named before this are taken in the order of their ids.
ALTER TABLE person_patron ADD COLUMN patron_order INT;
UPDATE person_patron pp SET patron_order = (
    SELECT COUNT(*) FROM person_patron q WHERE q.person_id = pp.person_id AND q.patron_id < pp.patron_id);
ALTER TABLE person_patron ALTER COLUMN patron_order SET NOT NULL;
ALTER TABLE person_patron DROP PRIMARY KEY;
ALTER TABLE person_patron ADD PRIMARY KEY (person_id, patron_order);
== V67__sheet_parent.sql
-- The sheet's parent: a sheet whose rates apply where this sheet has none in force. Null means none.
ALTER TABLE sheet ADD COLUMN parent_id VARCHAR(64);
== V68__claim_deleted.sql
-- A DRAFT claim may now be DELETED: it counts nowhere, and may be restored to a DRAFT on the sheet's
-- today it was deleted.
ALTER TABLE claim ADD COLUMN next_status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL
    CHECK (next_status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED'));
UPDATE claim SET next_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN next_status RENAME TO status;
== V69__pool_member_pool.sql
-- A pool's member may be another pool instead of a person, with a share like a person's. A pool is a
-- member of at most one pool; exactly one of person_id and member_pool_id is set.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_one_kind
    CHECK ((person_id IS NULL) <> (member_pool_id IS NULL));
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);
== V70__person_position.sql
-- People have a position in their sheet's list: the list, its rollup lines and every action taken in
-- list order follow it. People added before this keep the order they were added in.
ALTER TABLE person ADD COLUMN list_position INT;
UPDATE person p SET list_position = (SELECT COUNT(*) FROM person q WHERE q.sheet_id = p.sheet_id AND q.id <= p.id);
ALTER TABLE person ALTER COLUMN list_position SET NOT NULL;
== V71__person_origin.sql
-- The sheet a person was last transferred from; null when they were never transferred.
ALTER TABLE person ADD COLUMN origin_sheet_id VARCHAR(64);
== V72__pool_member_dates.sql
-- A pool membership may carry a from-date and a to-date, each optional: the member counts toward the
-- pool's total share and gets a cut only on days within them. A to-date is never before the from-date.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
ALTER TABLE pool_member ADD CONSTRAINT pool_member_to_after_from
    CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
== V73__person_retirement.sql
-- A retired person can be unretired: they are no longer retired, and the retirement is kept as a
-- past one, from its date to the day they were unretired. A person may have several over time; no
-- claim dated after the from and before the to of one can be added for them.
CREATE TABLE person_retirement (
    person_id BIGINT NOT NULL REFERENCES person (id),
    retirement_order INT NOT NULL,
    from_date DATE   NOT NULL,
    to_date   DATE   NOT NULL,
    PRIMARY KEY (person_id, retirement_order)
);
