package net.officefloor.hq.app.sheet;


/**
 * Refuse every change anyone asks for on an archived sheet: any request other than a read, or the
 * loading of the sheet, is turned away before it reaches its handler, so it writes nothing and audits
 * nothing. A bulk move is the exception: it reaches its handler, which refuses each claim selected.
 */
@Configuration
public class ArchiveGuard implements WebMvcConfigurer, HandlerInterceptor {

    private final SheetService sheets;

    public ArchiveGuard(SheetService sheets) {
        this.sheets = sheets;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        // A bulk move answers how many claims it refused, so it is let through and refuses each.
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load",
                "/api/sheets/*/claims/open", "/api/sheets/*/claims/settle");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
            return true;
        }
        Object variables = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(variables instanceof Map<?, ?> vars)) {
            return true;
        }
        Object sheetId = vars.containsKey("sheetId") ? vars.get("sheetId") : vars.get("id");
        if (sheetId instanceof String id && sheets.archived(id)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it may change.");
        }
        return true;
    }
}
package net.officefloor.hq.app.role;


/**
 * Refuse every change a viewer asks for on a sheet: any request other than a read, or the loading
 * of the sheet, is turned away before it reaches its handler, so it writes nothing and audits nothing.
 * A bulk move, a bulk grade and a bulk retire are the exceptions: each reaches its handler, which refuses each claim
 * or person a viewer selected.
 */
@Configuration
public class ViewerGuard implements WebMvcConfigurer, HandlerInterceptor {

    private final RoleService roles;

    public ViewerGuard(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        // A bulk move answers how many claims it refused, and a bulk grade or retire how many people it changed,
        // so a viewer's is let through and refuses each.
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load",
                "/api/sheets/*/claims/open", "/api/sheets/*/claims/settle", "/api/sheets/*/people/grade",
                "/api/sheets/*/people/retire");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
            return true;
        }
        String header = request.getHeader(SignedIn.HEADER);
        Object variables = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (header == null || !(variables instanceof Map<?, ?> vars)) {
            return true;
        }
        Object sheetId = vars.containsKey("sheetId") ? vars.get("sheetId") : vars.get("id");
        if (sheetId instanceof String id && Role.VIEWER.equals(roles.roleOf(id, SignedIn.name(header)))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer may not change anything on the sheet.");
        }
        return true;
    }
}
