/**
 * A person's figures: what they have claimed, their due-total (null when n/a) and their
 * overdue-total (the due of their counting overdue claims).
 */
public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {

    boolean sameAs(Figures other) {
        return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal)
                && same(overdueTotal, other.overdueTotal);
    }
}

/** The sheet's figures: each person's by id, in list order, and the sheet's totals. */
public record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
        BigDecimal overdueTotal) {
}

private final PersonRepository people;
private final ClaimRepository claims;
private final SheetRepository sheets;
private final Dues dues;
private final Audit audit;

public Rollups(PersonRepository people, ClaimRepository claims, SheetRepository sheets,
        Dues dues, Audit audit) {
    this.people = people;
    this.claims = claims;
    this.sheets = sheets;
    this.dues = dues;
    this.audit = audit;
}

/** The sheet's figures as they stand now in the current transaction. */
public Rollup take(String sheetId) {
    Sheet sheet = sheets.findById(sheetId).orElse(null);
    LocalDate today = sheet == null ? null : sheet.getToday();
    Dues.Basis basis = dues.live(sheetId);
    Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
    for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
        if (claim.getStatus().counts()) {
            byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
        }
    }
    Map<Long, Figures> figures = new LinkedHashMap<>();
    BigDecimal claimedTotal = zero();
    List<BigDecimal> dueFigures = new ArrayList<>();
    List<BigDecimal> overdueFigures = new ArrayList<>();
    for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
        List<Claim> counting = byPerson.getOrDefault(person.getId(), List.of()).stream()
                .filter(claim -> person.countsLive(claim.getStatus(), claim.getDate(), claim.isStated(), claim.isDeferredOn(today), today))
                .toList();
        BigDecimal claimed = zero();
        BigDecimal due = zero();
        BigDecimal overdue = zero();
        boolean figured = false;
        for (Claim claim : counting) {
            claimed = claimed.add(claim.getAmount());
            String grade = person.gradeOn(claim.getDate());
            BigDecimal figure = dues.due(claim, grade, basis);
            if (figure != null) {
                due = due.add(figure);
                figured = true;
                if (overdue(claim, sheet, grade)) {
                    overdue = overdue.add(figure);
                }
            }
        }
        // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
        // figure (a fixed one, or one at the grade in force on its own date).
        boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
        if (!rated && !figured) {
            due = null;
        }
        // A due-total is at most the sheet's cap.
        if (sheet != null) {
            due = sheet.capped(due);
        }
        figures.put(person.getId(), new Figures(person.getName(), claimed, due, overdue));
        claimedTotal = claimedTotal.add(claimed);
        if (due != null) {
            dueFigures.add(due);
        }
        overdueFigures.add(overdue);
    }
    return new Rollup(figures, claimedTotal, trimmed(dueFigures), trimmed(overdueFigures));
}

                StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
    } catch (IOException e) {
        throw new UncheckedIOException(e);
    }
}

/**
 * Append one audit record once the current transaction commits, so a change that is refused or
 * rolled back writes nothing. Records outside a transaction are appended at once.
 */
public void recordOnCommit(String entry) {
    recordAfterCommit(entry + actingFor());
}

/**
 * Append a record of the figures a change moved (ROLLUP and TOTALS) once the current transaction
 * commits; unlike the change's own records it never names a steward acted for.
 */
public void recordFiguresOnCommit(String entry) {
    recordAfterCommit(entry);
}

/** " for=<steward>" when the signed-in user acts for a steward in this request, else empty. */
private static String actingFor() {
    RequestAttributes request = RequestContextHolder.getRequestAttributes();
    Object steward = request == null ? null : request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST);
    return steward instanceof String name ? " for=" + name : "";
}

private void recordAfterCommit(String entry) {
    if (!TransactionSynchronizationManager.isSynchronizationActive()) {
        record(entry);
        return;
    }
    TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
        @Override
        public void afterCommit() {
            record(entry);
        }
    });
}

/** A field naming a person: name=&lt;value&gt; or person=&lt;value&gt;, the value running to the next field. */
private static final java.util.regex.Pattern PERSON_FIELD =
        java.util.regex.Pattern.compile(" (?:name|person)=(.*?)(?= [^ =]+=|$)");

